  } else {
    ui.弹出提示('💡 该算子正在端侧并网构建中...', 'info');
  }
};
const openOfficialWebsite = async () => {
  try {
    await openUrl('https://geantendormi.top/');
  } catch {
    window.open('https://geantendormi.top/', '_blank');
  }
};
